    requestId: text(
      dispatchRaw.trace.requestId,
      "trace.requestId",
      180,
    ),
    requestFingerprintSha256: sha(
      dispatchRaw.trace.requestFingerprintSha256,
      "trace.requestFingerprintSha256",
    ),
  },
}, "dispatchEnvelope", 0);
return [{
  json: {
    acquisitionCommand: {
      contractVersion:
        "risk-scan-public-lite-acquisition-command-v1",
      handoffId,
      executionId,
      scanRunId,
      dispatchEnvelope,
      attempt: raw.attempt,
      leaseToken,
    },
    dispatchEnvelope,
  },
